// This is a sketch for painting a sunset over green hills
// using the p5.brush library.

// The sun is located at the top left of the canvas
// The sky is green, and the hills are also green
// We use brush.fill to fill the sky and hills
// We use brush.fill to fill the details of the hills

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2); // Scale the brush to make it smaller
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2); // Move the canvas to the center
  background("#f4efe4"); // Set the background color

  // Paint the sky
  brush.fill("#e08a72", 1); // Set the sky color to a dark green and full opacity
  brush.beginShape(); // Begin a shape
  brush.vertex(0, 0); // Start of the sky
  brush.vertex(0, 300); // End of the sky
  brush.endShape(true); // End the shape

  // Paint the green hills
  brush.fill("#908728", 1); // Set the hill color to a dark green and full opacity
  brush.beginShape(); // Begin a shape
  brush.vertex(0, 200); // Start of the hill
  brush.vertex(200, 200); // End of the hill
  brush.vertex(400, 200); // End of the hill
  brush.endShape(true); // End the shape

  // Paint the details of the hills
  brush.fill("#706220", 1); // Set the hill color to a light green and full opacity
  brush.beginShape(); // Begin a shape
  brush.vertex(0, 150); // Start of the hill
  brush.vertex(200, 150); // End of the hill
  brush.vertex(400, 150); // End of the hill
  brush.endShape(true); // End the shape
}

