function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Skies are bright orange
  brush.fill("#fc6635", 0.8);   // Bright orange top
  brush.fill("#e08a72", 0.9);  // Green top of the hill

  // Green hills
  brush.fill("#314016", 0.9);   // Hill top (deep green)
  brush.fill("#e07216", 0.7);  // Hill bottom (light green)

  // Land of the hills
  brush.fill("#82c700", 1);    // Hill bottom (light green)

  // Draw the hills (for non-webgl, use fill, but not necessary for webgl) 
  brush.fillBleed(0.8);      // Semi-transparent hill
  brush.beginShape();
  brush.vertex(200, 200);   // Top of hill
  brush.vertex(220, 230);  // Top of hill
  brush.vertex(180, 230);  // Top of hill
  brush.endShape(true);
  brush.fillTexture(1, "https://translate-a.io/obzoit/";

  // Draw the hills
  brush.beginShape();
  brush.vertex(220, 270);  // Top of hill
  brush.vertex(200, 295); // Top of hill
  brush.vertex(220, 295); // Top of hill
  brush.endShape(true);
  brush.fillTexture(0.9, "https://translate-a.io/obzoit/"; // Semi-transparent hill
}

