// Paint a sunset over green hills
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Start with the sky
  brush.fill("#e08a72", 85); // Sky color with 85% opacity
  brush.fillBleed(1); // Since it's the sky, it's more opaque
  brush.circle(0, 0, 400); // A huge circle for the sky

  // Then the green hills
  brush.fill("#452020", 25); // Green hills with 25% opacity
  brush.fillBleed(1); // The hills are a little more detailed
  brush.circle(0, 100, 200); // A hill and a bit more of a hill
  brush.beginShape();
  brush.vertex(200, 100);
  brush.vertex(100, 300);
  brush.vertex(0, 100);
  brush.vertex(-200, 300);
  brush.endShape(true);

  // Add some more hills to the hills to make the green hills look a bit like hills
  brush.fill("#452020", 25);
  brush.fillBleed(1); // The hills are a little more detailed
  brush.beginShape();
  brush.vertex(150, 220); // A hill and a bit more of a hill
  brush.vertex(100, 250); // A hill and a bit more of a hill
  brush.vertex(0, 300); // A hill and a bit more of a hill
  brush.endShape(true);
}

