// Painting a sunset over green hills
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#349853", 30); // Sky blue
  brush.fill("#338558", 60); // Dark blue for the clouds
  brush.fill("#112949", 85); // Deep blue for the horizon
  brush.fill("#472516", 95); // Darker sky
  brush.beginShape();
  brush.vertex(0, 0); // Top of the hill
  brush.vertex(200, 120); // Bottom of the hill
  brush.vertex(400, 0); // Bottom of the hill
  brush.endShape(true);

  // Hills
  brush.fill("#b84337", 10); // Green hill
  brush.fill("#7f342b", 80); // Lighter green hill
  brush.fill("#6f3a36", 80); // Darker green hill
  brush.fill("#797747", 30); // Dark green hill
  brush.beginShape();
  brush.vertex(0, 80); // Top of the hill
  brush.vertex(200, 110); // Bottom of the hill
  brush.vertex(400, 80); // Bottom of the hill
  brush.endShape(true);

  // Horizon
  brush.fill("#a6134a", 120); // Red for the sunset
  brush.fill("#d90a2b", 60); // Dark red for the clouds
  brush.beginShape();
  brush.vertex(0, 280); // Top of the hill
  brush.vertex(200, 360); // Bottom of the hill
  brush.vertex(400, 280); // Bottom of the hill
  brush.endShape(true);

  // Sun
  brush.fill("#d92222", 10); // Golden yellow for the sun
  brush.beginShape();
  brush.vertex(200, 420); // Top of the sun
  brush.vertex(0, 460); // Bottom of the sun
  brush.vertex(400, 460); // Bottom of the sun
  brush.endShape(true);
}
