// Painting a sunset over green hills
// using p5.brush library (global `brush`)

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2); // translate to draw in 2D
  background("#f4efe4"); // background color
  brush.fillStyle("skyblue"); // set fill color to sky blue
  brush.fill(); // fill the canvas

  // Paint the hills
  brush.fillStyle("#6b8e23"); // set fill color to green hill
  brush.fill(); // fill the hills
  brush.fillBleed(0.3); // add a bit of red for the sun
  brush.fill(); // fill the hills

  // Paint the sun
  brush.fillStyle("#ffa500"); // set fill color to yellow for the sun
  brush.fill(); // fill the sun
}

