// Painting a sunset over green hills
// Background is a sky, hills are green, and a sun in the top left corner

// Syntax
// 1. brush.noFill()      // no stroke
// 2. brush.fillBleed(0.5)    // 50% of shape filled, 0-1
// 3. brush.fillTexture(1, true)   // solid color hill, true for 100% hill with no outline
// 4. brush.beginShape(...)        // start a shape
// 5. brush.vertex(x, y)         // position
// 6. brush.endShape(true)       // finish shape

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  // Paint sky
  brush.fill('#e08a72', 0.5); // fill sky with a color with some transparency
  brush.fillBleed(0.5);       // 50% of shape filled
  brush.fillTexture(1, true);  // solid color hill, true for 100% hill with no outline
  brush.beginShape();
  brush.vertex(200, 0);        // hill's top, at the center of the canvas
  brush.vertex(0, 300);      // bottom left hill
  brush.vertex(0, 20);       // bottom left hill, slightly more forward
  brush.vertex(400, 20);    // bottom right hill, slightly more forward
  brush.endShape(true);      // finish shape

  // Paint hill background
  brush.fill('#f7e6e6', 0.5);
  brush.beginShape();
  brush.vertex(0, 0);       // bottom left hill
  brush.vertex(400, 0);   // bottom right hill
  brush.endShape(true);

  // Paint hills again, lower and a bit on the right
  brush.fill('#8d4d1e', 0.1); // less green, a little more light
  brush.beginShape();
  brush.vertex(0, 400);      // top left hill
  brush.vertex(400, 400);   // top right hill
  brush.endShape(true);      // finish shape

  // Paint sun
  brush.fill('red');       // fill with red (solid color)
  brush.fillBleed(1);     // 100% of shape filled
  brush.beginShape();
  brush.vertex(0, 150);    // top left hill
  brush.vertex(0, 15);    // bottom left hill
  brush.vertex(400, 15);   // bottom right hill
  brush.endShape(true);      // finish shape
}

