// Paint a sunset over green hills
// Painting over green hills
// Each hill's color is a gradient of red to orange
// On top of that, a sky blue background is painted.

function setup() {
  createCanvas(400, 400, WEBGL);
  // Scale brushes down slightly
  brush.scaleBrushes(0.7);
  // Load a gradient from red to orange for the hills
  // This is a rough gradient; you may need to adjust it for the hills' specific shape
  brush.fillGradient(brush.hslToRgb(20, 100, 50), brush.hslToRgb(30, 100, 100), 0.05);
  // Load a sky blue background
  brush.fill("skyblue", 0.1);
  // Load a sky blue background with a small drop in the bottom of the hills
  brush.fill("skyblue", 0.3, 0.1);
  // Begin a shape that draws the hill from top to bottom
  brush.beginShape();
  // First hill
  brush.vertex(0, 0);
  brush.vertex(0, 200);
  brush.endShape(true);
  // Second hill, a bit lower
  brush.beginShape();
  brush.vertex(0, 100);
  brush.vertex(0, 300);
  brush.endShape(true);
}
