// Painting a sunset over green hills using the p5.brush library
// Drawing over the sky, then the hills, and then the trees
// We draw the hills first, and then the sun, with a small red spot

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Sky: a green gradient, starting from the top
  brush.fill("#b4d89b", 120); // from top to bottom
  brush.fill("#9ebc72", 30); // from top to bottom
  brush.fill("#81a384", 15); // from top to bottom
  brush.fill("#798762", 5);  // from top to bottom

  // Drawing a green hill background on top of the sky
  brush.fill("#b4d89b", 80); // hill
  brush.fill("#b3e06b", 70); // hill
  brush.fill("#80895b", 45); // hill
  brush.fill("#3b3f05", 70); // hill

  // Paint hills, then trees
  brush.fill("#3b4b4b", 100); // hill
  brush.fill("#80895b", 15); // hill
  brush.fill("#28352a", 30); // hill

  // Paint the sun, with a small red spot on top
  brush.fill("#ffc42c", 80); // sun
  brush.fill("#ff4040", 60); // spot

  brush.beginShape();
  brush.vertex(0, 0);  // top of hill
  brush.vertex(160, -25);  // middle of hill
  brush.vertex(320, -25);  // middle of hill
  brush.vertex(400, 0);  // top of hill

  brush.endShape(true);

  // trees
  brush.beginShape();
  brush.vertex(0, 40);  // top of tree
  brush.vertex(160, -20);  // middle of tree
  brush.vertex(320, -20);  // middle of tree
  brush.vertex(400, 40);  // top of tree
  brush.endShape(true);
}

